import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.oeh4wjV1.js";const h=JSON.parse('{"title":"Jumpstart","description":"","frontmatter":{},"headers":[],"relativePath":"formats/jumpstart/index.md","filePath":"formats/jumpstart/index.md","lastUpdated":1792425987000}'),o={name:"formats/jumpstart/index.md"};function n(i,e,l,c,d,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="jumpstart" tabindex="-1">Jumpstart <a class="header-anchor" href="#jumpstart" aria-label="Permalink to &quot;Jumpstart&quot;">​</a></h1><p><a href="./../">All formats</a></p><p>Jumpstart combines two prepared, themed twenty-card packets into one forty-card deck. Lands are already included, so players can choose their packets and start playing without a deck-building session.</p><h2 id="play-rules" tabindex="-1">Play rules <a class="header-anchor" href="#play-rules" aria-label="Permalink to &quot;Play rules&quot;">​</a></h2><ul><li><a href="./variants/two-packet.html">Two-packet Jumpstart: full rules</a>, covering packet selection, deck assembly, opening hands, mulligans, play, victory, and resetting for another game.</li></ul><h2 id="build-a-reusable-box" tabindex="-1">Build a reusable box <a class="header-anchor" href="#build-a-reusable-box" aria-label="Permalink to &quot;Build a reusable box&quot;">​</a></h2><ul><li><a href="./building-packets.html">Building and labeling custom packets</a>, covering card selection, lands, the catalogue&#39;s preference for variety, packet identifiers, double sleeves with protected thematic stickers, and quick cleanup.</li></ul><p>Official Jumpstart packets and custom packets can both supply this play structure. Custom boxes should state their card pool, packet-selection method, supported combinations, and any changes to the play rules. A packet&#39;s theme does not itself change how its cards work.</p><p>For this catalogue&#39;s reusable custom packets, every card receives its packet&#39;s small identifying sticker on the <strong>front of an inner sleeve</strong>, protected inside an <strong>identical opaque-backed outer sleeve</strong>. Matching symbols let players sort the packets after play while the card backs remain indistinguishable.</p><p>See <a href="./../../boxed-sets/">boxed sets</a> for individual play kits and <a href="./../../rules/">Using the rules</a> for how a box records its base rules and exceptions.</p><p>Sources: <a href="https://magic.wizards.com/en/products/jumpstart" target="_blank" rel="noreferrer">Wizards&#39; Jumpstart overview and FAQ</a> and <a href="https://magic.wizards.com/en/news/announcements/introducing-jumpstart-new-way-play-magic-2020-02-20" target="_blank" rel="noreferrer">Introducing Jumpstart</a>. The custom-packet preparation method is a local catalogue convention.</p>',11)])])}const m=a(o,[["render",n]]);export{h as __pageData,m as default};
